files.content:
:root {
  --bg: #1b1f3b;
  --card: #2a2f5a;
  --ink: #f4f4ff;
  --muted: #b8bce0;
  --accent: #ffd166;
  --accent-2: #06d6a0;
  --border: #0d1024;
  --shadow: #0d1024;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  min-height: 100%;
}

body {
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  color: var(--ink);
  background-color: var(--bg);
  background-image: linear-gradient(135deg, #1b1f3b 0%, #23284d 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
}

.card {
  width: 100%;
  max-width: 420px;
  background: var(--card);
  border: 4px solid var(--border);
  box-shadow: 8px 8px 0 var(--shadow);
  padding: 28px 24px;
}

h1 {
  margin: 0 0 4px;
  font-size: 1.75rem;
  letter-spacing: 0.5px;
  color: var(--accent);
  text-transform: uppercase;
}

.subtitle {
  margin: 0 0 24px;
  color: var(--muted);
  font-size: 1rem;
}

.field {
  margin-bottom: 20px;
  border: 0;
  padding: 0;
}

label, legend {
  display: block;
  font-weight: 700;
  margin-bottom: 8px;
  font-size: 1rem;
}

.input-wrap {
  display: flex;
  align-items: center;
  background: #141834;
  border: 3px solid var(--border);
}

.prefix {
  padding: 0 12px;
  color: var(--accent);
  font-weight: 700;
}

input[type="number"] {
  width: 100%;
  font: inherit;
  font-size: 1.125rem;
  padding: 12px;
  color: var(--ink);
  background: transparent;
  border: 3px solid var(--border);
  outline: none;
}

.input-wrap input {
  border: 0;
}

input[type="number"]:focus-visible,
.input-wrap:focus-within {
  outline: 3px solid var(--accent-2);
  outline-offset: 2px;
}

.tip-group {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}

.tip-btn {
  font: inherit;
  font-weight: 700;
  font-size: 1.125rem;
  padding: 12px 8px;
  color: var(--ink);
  background: #141834;
  border: 3px solid var(--border);
  cursor: pointer;
  box-shadow: 3px 3px 0 var(--shadow);
  transition: transform 0.05s ease, box-shadow 0.05s ease, background 0.15s ease;
}

.tip-btn:hover {
  background: #1d2350;
}

.tip-btn:focus-visible {
  outline: 3px solid var(--accent-2);
  outline-offset: 2px;
}

.tip-btn:active {
  transform: translate(3px, 3px);
  box-shadow: 0 0 0 var(--shadow);
}

.tip-btn[aria-pressed="true"] {
  background: var(--accent);
  color: #1b1f3b;
  border-color: var(--accent);
}

.results {
  margin-top: 24px;
  padding: 16px;
  background: #141834;
  border: 3px solid var(--border);
  box-shadow: 4px 4px 0 var(--shadow);
}

.result-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 12px;
  padding: 6px 0;
}

.result-row.total {
  border-top: 2px dashed var(--muted);
  margin-top: 6px;
  padding-top: 12px;
}

.result-label {
  color: var(--muted);
  font-size: 1rem;
}

.result-value {
  font-weight: 700;
  font-size: 1.25rem;
  color: var(--accent-2);
  word-break: break-all;
  text-align: right;
}

.result-row.total .result-value {
  color: var(--accent);
  font-size: 1.5rem;
}

@media (max-width: 380px) {
  .card { padding: 22px 16px; }
  h1 { font-size: 1.5rem; }
  .result-value { font-size: 1.125rem; }
  .result-row.total .result-value { font-size: 1.25rem; }
}

(function () {
  'use strict';

  var billInput = document.getElementById('bill');
  var peopleInput = document.getElementById('people');
  var tipButtons = Array.prototype.slice.call(document.querySelectorAll('.tip-btn'));
  var tipOut = document.getElementById('tipPerPerson');
  var totalOut = document.getElementById('totalPerPerson');

  var selectedTip = 15;

  function formatMoney(value) {
    if (!isFinite(value) || value < 0) value = 0;
    return '$' + value.toFixed(2);
  }

  function calculate() {
    var bill = parseFloat(billInput.value);
    var people = parseInt(peopleInput.value, 10);

    if (!isFinite(bill) || bill < 0) bill = 0;
    if (!isFinite(people) || people < 1) people = 1;

    var tipTotal = bill * (selectedTip / 100);
    var tipPerPerson = tipTotal / people;
    var totalPerPerson = (bill + tipTotal) / people;

    tipOut.textContent = formatMoney(tipPerPerson);
    totalOut.textContent = formatMoney(totalPerPerson);
  }

  function selectTip(button) {
    selectedTip = parseInt(button.getAttribute('data-tip'), 10);
    tipButtons.forEach(function (btn) {
      btn.setAttribute('aria-pressed', btn === button ? 'true' : 'false');
    });
    calculate();
  }

  tipButtons.forEach(function (button) {
    button.addEventListener('click', function () {
      selectTip(button);
    });
  });

  billInput.addEventListener('input', calculate);
  peopleInput.addEventListener('input', calculate);

  // Normalize people count when leaving the field.
  peopleInput.addEventListener('blur', function () {
    var people = parseInt(peopleInput.value, 10);
    if (!isFinite(people) || people < 1) {
      peopleInput.value = '1';
    }
    calculate();
  });

  calculate();
})();
